    public static void solve()  {
//////////////////////////////////////////////////////////////////////
        String s = sc.next(),t=sc.next();
        int ss=s.length(),tt=t.length();
        int match;
        int pos;
        int max_match=0;
        boolean is;
        for (int i = 0; i < tt; i++) {
            pos=i;
            match=0;
            is =false;
            for (int j = 0; j < ss; j++) {
                if(s.charAt(j)==t.charAt(pos)){
                    if(j>=pos&& ss-j>=tt-pos) {
                        match++;
                        max_match=Math.max(match,max_match);
                        is=true;
                    }

                }
                if(is) pos++;
                if(pos>=tt){
                    pos=i;
                    match=0;
                    is=false;
                }
            }

        }
        System.out.println(tt-max_match);
///////////////////////////////////////////////////////////////////////
    }

