            for (int i = 0; i < 3; i++) {
                char next = s.charAt(i);
                if (next == 'R') {
                    counter++;
                } else {
                    counter = 0;
                }
                result = Math.max(result, counter);
            }
            System.out.println(result);
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

