		Integer[] acmsd = new Integer[inA.size()];

		int acm = inA.get(0);
		acms[0] = acm;

		// create accumulation list
		for(int i = 1; i < inN; i++) {
			acm = calc(acm, inA.get(i));
			acms[i] = acm;
		}

		acm = inA.get(inN - 1);
		acmsd[0] = acm;
		int j = 0;
		for(int i = inN - 1; i >= 0; i--) {
			acm = calc(acm, inA.get(i));
			acmsd[j] = acm;
			j++;
		}


		int max = 0;

		for(int i = inN - 1; i >= 0; i--) {

