import java.util.*;

public class Main {
	static class Node {
		Node parent;
		int value;
		Node right, left;

		Node(int value) {
			this.value = value;
			this.parent = null;
			this.right = null;
			this.left = null;
		}

		/**
		 * 値を追加して，rootのnodeを返す
		 * 
		 * @param value
		 * @return
		 */
		Node add(int value) {
			if (this.value >= value) {
				Node parent = new Node(value);
				parent.left = this;
				this.parent = parent;
				return parent;
			} else if (this.left == null && this.right == null) {
				this.right = new Node(value);
				this.right.parent = this;
				return this;
			} else if(this.right== null){
				if(this.left.value <= value) {
					// 右側につける
					this.right = new Node(value);
					this.right.parent = this;
					return this;
				}else {
					this.left.add(value);
					return this;
				}
			}else {
				// right != null && left == null
				if(this.right.value < value) {
					this.right.add(value);
					return this;
				}else {
					Node middle = new Node(value);
					middle.left = this.right;
					this.right.parent = middle;

				}

				if (this.right.value < value) {
					this.right.add(value);
					return this;
				} else {
					Node middle = new Node(value);
					middle.left = this.right;
					this.right = middle;
					return this;
				}
			}
		}

		long getCost(long base) {
			if (this.left == null && this.right == null) {
				return this.value - base;
			} else if (this.left != null && this.right != null) {
				long result = 0;
				result += this.left.getCost(this.value);
				result += this.right.getCost(this.value);
				result += this.value - base;
				return result;
			} else if (this.left != null) {
				// leftのみ
				long result = 0;
				result += this.left.getCost((this.value));
				result += this.value - base;
				return result;
			} else {
				// rightのみ
				long result = 0;
				result += this.right.getCost(this.value);
				result += this.value - base;
				return result;
			}
		}
	}

	int N;
	int[] h;
	List<Deque<Integer>> sections;

	Main() {
		Scanner in = new Scanner(System.in);
		N = Integer.parseInt(in.nextLine());
		String[] tokens = in.nextLine().split(" ");
		h = new int[N];
		for (int i = 0; i < N; ++i) {
			h[i] = Integer.parseInt(tokens[i]);
		}
		in.close();
	}

	Node genTree(int[] h) {
		// 最初のnodeを作る
		Node root = new Node(h[0]);
		for (int i = 1; i < h.length; ++i) {
			root = root.add(h[i]);
		}
		return root;
	}

	public static void main(String[] args) {
		Main ins = new Main();
		Node root = ins.genTree(ins.h);
		System.out.println(root.getCost(0));
	}

}

/**
 * ３つの整数を読み込み、それらを値が小さい順に並べて出力するプログラム
 * @author 前島佑介
 *@version 2014/12/1
 */
import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;


// 2-C ３つの整数を読み込み、それらを値が小さい順に並べて出力するプログラム
class Main {

	// プログラムのエントリポイント
	public static void main(String[] args) {

		//入力値1つ目
		int intNum1 = 0;

		//入力値2つ目
		int intNum2 = 0;

		//入力値2つ目
		int intNum3 = 0;

		try{
			//キーボードからの入力準備
			BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

			//キーボードからの入力をString型で受け取る
			String strLine = br.readLine();

			//文字列の分割:入力値を" "で分ける
			//分けた文字列はstrLineAry[0]とstrLineAry[1]に分けられる
			String[] strLineAry = strLine.split(" ");

			//入力値の１つ目の値
			intNum1 = Integer.parseInt(strLineAry[0]);

			//２つ目の値
			intNum2 = Integer.parseInt(strLineAry[1]);

			//３つ目の値
			intNum3 = Integer.parseInt(strLineAry[2]);

			//入れ替えする為の場所
			int intChange = 0;

			//intNum1よりintNum2のほうが小さいなら
			//intNum1とintNum2を入れ替える
			if(intNum1 > intNum2) {
				intChange = intNum1;
				intNum1 = intNum2;
				intNum2 = intChange;
			}

			//intNum2よりintNum3のほうが小さいなら
			//intNum1とintNum2を入れ替える
			if(intNum2 > intNum3) {
				intChange = intNum2;
				intNum2 = intNum3;
				intNum3 = intChange;
			}

			//intNum1よりintNum2のほうが小さいなら
			//intNum1とintNum2を入れ替える
			if(intNum1 > intNum2) {
				intChange = intNum1;
				intNum1 = intNum2;
				intNum2 = intChange;
			}

			//結果を出力
			System.out.println(intNum1 + " " + intNum2 + " " + intNum3);

			//例外処理
			}catch(IOException e) {

				//例外時の出力
				System.out.println(e);

			}catch(NumberFormatException e) {

				//数値以外の入力値で出力
				System.out.println("数値で入力して下さい");
			}
	}
}

