        final long C = sc.nextLong();
        final long D = sc.nextLong();

        System.out.println(B - A + 1 - MyLib.countMultiples(A, B, C) - MyLib.countMultiples(A, B, D) + MyLib.countMultiples(A, B, MyLib.lcm(C, D)));
    }
