    static class Pair<F extends Comparable<F>, S extends Comparable<S>> implements Comparable<Pair<F, S>> {
        F f;
        S s;

        Pair() {
        }

        Pair(F f, S s) {
            this.f = f;
            this.s = s;
        }

        Pair(Pair<F, S> p) {
            f = p.f;
            s = p.s;
        }

        @Override
        public int compareTo(Pair<F, S> p) {
            if (f.compareTo(p.f) != 0) {
                return f.compareTo(p.f);
            }
            return s.compareTo(p.s);
        }

        @Override
        public int hashCode() {
            return f.hashCode() ^ s.hashCode();
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) {
                return true;
            }
            if (o == null || this.f == null || this.s == null) {
                return false;
            }
            if (this.getClass() != o.getClass()) {
                return false;
            }
            Pair p = (Pair) o;
            return this.f.equals(p.f) && this.s.equals(p.s);
        }

        @Override
        public String toString() {
            return "{" + f.toString() + ", " + s.toString() + "}";
        }
    }

    class BIT<T> {
        int n;
        ArrayList<T> bit;
        BiFunction<T, T, T> bif;

        /**
         * 1-indexed なBinary Indexed Treeを構築する
         *
         * @param n   容量
         * @param bif 適用させる関数
         * @param sup 初期値
         */
        BIT(int n, BiFunction<T, T, T> bif, Supplier<T> sup) {
            this.n = n;
            bit = new ArrayList<>(n + 1);
            for (int i = 0; i < n + 1; ++i) {
                bit.add(sup.get());
            }
            this.bif = bif;
        }

        /**
         * iの位置の値をvで更新する
         *
         * @param i index
         * @param v 新しい値
         */
        void set(int i, T v) {
            for (int x = i; x <= n; x += x & -x) {
                bit.set(x, bif.apply(bit.get(x), v));
            }
        }

        /**
         * クエリー
         *
         * @param defaultValue 初期値
         * @param i            index
         * @return [1, i]までfを適用した結果
         */
        T reduce(T defaultValue, int i) {
            T ret = defaultValue;
            for (int x = i; x > 0; x -= x & -x) {
                ret = bif.apply(ret, bit.get(x));
            }
            return ret;
        }
    }

    class SegmentTree<T> {
        int n;
        ArrayList<T> dat;
        BiFunction<T, T, T> bif;
        Supplier<T> sup;

        /**
         * 0-indexed なSegment Treeを構築する
         *
         * @param n_  要求容量
         * @param bif 適用させる関数
         * @param sup 初期値
         */
        SegmentTree(int n_, BiFunction<T, T, T> bif, Supplier<T> sup) {
            n = 1;
            while (n < n_)
                n *= 2;

            dat = new ArrayList<>(2 * n - 1);
            for (int i = 0; i < 2 * n - 1; ++i) {
                dat.add(sup.get());
            }
            this.bif = bif;
            this.sup = sup;
        }

        /**
         * kの位置の値をvで更新する
         *
         * @param k index
         * @param v 新しい値
         */
        void set(int k, T v) {
            k += n - 1;
            dat.set(k, v);
            while (k > 0) {
                k = (k - 1) / 2;
                dat.set(k, bif.apply(dat.get(k * 2 + 1), dat.get(k * 2 + 2)));
            }
        }

        /**
         * クエリー
         *
         * @param l はじめ
         * @param r おわり
         * @return [l, r)での演算bifを適用した結果を返す
         */
        T reduce(int l, int r) {
            return _reduce(l, r, 0, 0, n);
        }

        T _reduce(int a, int b, int k, int l, int r) {
            if (r <= a || b <= l)
                return sup.get();
            if (a <= l && r <= b)
                return dat.get(k);
            T vl = _reduce(a, b, k * 2 + 1, l, (l + r) / 2);
            T vr = _reduce(a, b, k * 2 + 2, (l + r) / 2, r);
            return bif.apply(vl, vr);
        }
    }

    class UnionFind {
        int[] par;

        UnionFind(int n) {
            par = new int[n];
            for (int i = 0; i < n; ++i) {
                par[i] = i;
            }
        }

        int find(int x) {
            if (par[x] == x) {
                return x;
            }
            return par[x] = find(par[x]);
        }

        boolean same(int x, int y) {
            return find(x) == find(y);
        }

        void union(int x, int y) {
            x = find(x);
            y = find(y);
            if (x == y) {
                return;
            }
            par[x] = y;
        }
    }
}

import java.util.*;
import java.io.*;

class Main{
    public static void main(String args[])throws IOException{
        try(BufferedReader br = new BufferedReader(new InputStreamReader(System.in))){
            String[] input = br.readLine().split(" ");
            double A = Double.parseDouble(input[0]);
            double B = Double.parseDouble(input[1]);
            double H = Double.parseDouble(input[2]);
            double M = Double.parseDouble(input[3]);

            double h_r = 0;
            double m_r = 0;
            double r = 0;
            double result = 0;

            if(H == 0){
              h_r = 360;
            }else{
              h_r = H * 30;
            }

            if(M == 0){
              m_r = 360;
            }else{
              m_r = M * 6;
            }

            //System.out.println(h_r);
            //System.out.println(m_r);

            if(H == M){
              result = 0;
            }else{
              r = Math.abs(h_r - m_r);
              double cos = Math.cos(Math.toRadians(r));
              double a = Math.pow(A, 2);
              double b = Math.pow(B, 2);
              double tmp = a + b - (2 * A * B * cos);
              result = Math.sqrt(tmp);
            }

            System.out.println(result);
        }

    }
}

