		int N = sc.nextInt();
		int M = sc.nextInt();
		int p[] = new int[M];
		String S[] = new String[M];
		Set correctSet = new HashSet<Integer>();
		Set wrongSet = new HashSet<Integer>();
		Set submitAnswer = new HashSet<Integer>();
		int correct = 0;
		int wrong = 0;

		for (int i = 0; i < M; i++) {
