            if (stairs[i] < stairs[i - 1]) {
                newValues[i - 1] = stairs[i - 1] - 1;
            }
            newValues[i] = stairs[i];
        }
        boolean can = true;
        for (int i = 1; i < newValues.length; i++) {
            if (newValues[i - 1] > newValues[i]) {
                can = false;
                break;
            }
        }
        if (can) {
            System.out.println("Yes");
        } else {
            System.out.println("No");
        }
    }
}

