                b = Integer.parseInt(st.nextToken());
            }
            switch (op) {
                case "+":
                    answer = a + b;
                    break;
                case "-":
                    answer = a - b;
                    break;
                case "*":
                    answer = a * b;
                    break;
                case "/":
                    answer = a / b;
                    break;
            }
            if(op == "?") break;
        }

        System.out.println(answer);
    }

}

