import java.util.Scanner;

class Work {
	String name;
	int time;

	Work(String n,int t){
		name=n;  time=t;
	}

}

class Queue {
	int head;
	int tail;
	Work[] a;

	/*コンストラクタ*/
	Queue(int n){
		head=0; tail=-1; a=new Work[n];
	}

	void enqueue(Work x,int n){
		tail=(tail+1)%n;
		a[tail]=x;
	}

	Work dequeue(int n){
		Work temp=a[head];
		head=(head+1)%n;
		return temp;
	}

	void decrease(int t){
		a[head].time-=t;
	}

	int getTime(){
		return a[head].time;
	}

	String getName(){
		return a[head].name;
	}

}

class Main {

	static void solve(Queue Q,int n,int q,int sum){
		int time=0;
		Work temp;

		while(time != sum){
			if(Q.getTime() == q){
				time+=q;
				System.out.println(Q.getName() + " " + time);
				temp=Q.dequeue(n);
			}
			else if(Q.getTime() < q){
				time+=Q.getTime();
				System.out.println(Q.getName() + " " + time);
				temp=Q.dequeue(n);
			}
			else {
				time+=q;
				Q.decrease(q);
				temp=Q.dequeue(n);
				Q.enqueue(temp,n);
			}
		}

		return;
	}



	public static void main(String[] args){
		Scanner scan=new Scanner(System.in);

		int n=scan.nextInt();
		int q=scan.nextInt();
		int sum=0;
		Queue Q=new Queue(n);

		for(int i=0;i<n;i++){
			Work temp=new Work(scan.next(),scan.nextInt());
			Q.enqueue(temp,n);
			sum+=temp.time;
		}

		solve(Q,n,q,sum);

	}
}

import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

/**
 * AtCoder Beginner Contest 129<br>
 * B - Balance<br>
 * <br>
 * <a href="https://atcoder.jp/contests/abc129/tasks/abc129_b">AtCoderへのリンク</a><br>
 */
public class Main {

    /**
     * エントリポイント
     */
    public static void main(String[] args) {
        // 入力
        Model m = input(System.in);
        // 演算
        int result = proc(m);
        // 出力
        System.out.println(result);
    }

    /**
     * 入力モデル
     */
    static class Model {
        /** オモリの数 */
        int N;
        /** オモリの重さリスト */
        List<Integer> list = new ArrayList<Integer>();
    }

    /**
     * 入力値より入力モデルを作成する
     */
    private static Model input(InputStream in) {
        Model m = new Model();
        try (Scanner sc = new Scanner(in)) {
            String[] line1 = sc.nextLine().split(" ");
            String[] line2 = sc.nextLine().split(" ");

            m.N = Integer.parseInt(line1[0]);
            for (String str : line2) {
                m.list.add(Integer.parseInt(str));
            }
        }
        return m;
    }

    /**
     * 演算を行う
     */
    static int proc(final Model m) {
        //int result = 0;
        // TODO:実装する

        int sum = 0;
        int s1 = 0;
        int s2 = 0;
        // intの最大許容数をセット
        int min = Integer.MAX_VALUE;

        // 全要素合計算出
        for (int i=0; i<m.list.size(); i++) {
            sum += m.list.get(i);
        }

        for (int i=0; i<m.N; i++) {
            s1 = 0;
            s2 = 0;
            for (int j=0; j<=i; j++) {
                s1 += m.list.get(j);
            }
            s2 = sum - s1;
            if (min > Math.abs(s1 - s2)) {
                min = Math.abs(s1 - s2);
            }
        }

        return min;
    }
}

