import java.util.Arrays;
import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Main {
    private static boolean isComposable(String s, Set<String> dictionary) {
        if (dictionary.contains(s) || s.length() == 0) {
            return true;
        }

        for (int i=0; i<s.length(); i++) {
            String curr = s.substring(0, i);
            while (dictionary.contains(curr) && isComposable(s.substring(i), dictionary) ) {
                return true;
            }
        }

        return false;
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.nextLine();
        sc.close();
        Set<String> set = new HashSet<>(Arrays.asList(new String[]{"dream", "dreamer", "erase", "eraser"}));
        boolean canMake = isComposable(s, set);
        System.out.println(canMake ? "YES" : "NO");
    }
}

import java.util.*;
public class Main {
  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);
    long a = sc.nextLong();

    long b = Long.MAX_VALUE /2;
    long c = Long.MAX_VALUE /2;
    List<Long> list = factorization(a);
    for (long i : list) {
        if((a/i + i) < (b + c) ){
          b = a/i;
          c = i;
        }
    }
    System.out.println(b + c -2);
  }

  static List<Long> factorization(long x) {
    List<Long> result = new ArrayList<>();

    while (x >= 4 && x % 2 == 0) {
        result.add((long)2);
        x /= 2;
    }
    long d = 3;
    long q = x / d;
    while (q >= d) {
        if (x % d == 0) {
            result.add(d);
            x = q;
        } else {
            d += 2;
        }
        q = x / d;
    }
    result.add(x);
    return result;
  }
}

