        }
        for(int i = 0; i < n; i++){
            tempb[i] = b[i];
        }


        int sum1 = 0;
        int sum2 = 0;
        for(int i = 0; i < n; i++){
            int min1 = Math.min(a[i], b[i]);
            a[i] -= min1;
            b[i] -= min1;
            sum1 += min1;
            int min2 = Math.min(a[i+1], b[i]);
