				c = (B - (A / C + 1) * C) / C + 1;
			} else {
				c = (B - C) / C + 1;
			}
		} else {
			c = (B - A) / C + 1;
		}

		if(A % D != 0) {
			if(A > D) {
				d = (B - (A / D + 1) * D) / D + 1;
			} else {
				d = (B - D) / D + 1;
			}
		} else {
			d = (B - A) / D + 1;
		}

		if(A % koub != 0) {
			if(A > koub) {
				cd = (B - (A / koub + 1) * koub) / koub + 1;
			} else {
				cd = (B - koub) / koub + 1;
			}
		} else {
			cd = (B - A) / koub + 1;
		}

		System.out.println(B - A + 1 - c - d + cd);
	}

	public static long gcd(long a, long b) {
		if(b == 0) {
			return a;
		}
		return gcd(b, a % b);
	}
}

