            int sum = C;
            for (int j = 0; j < M; ++j) {
                sum += A[i][j]*B[j];
            }
            if (sum > 0) {
                answer++;
            }
        }

        System.out.println(answer);
        System.out.flush();
        sc.close();
    }
}

