    }

    private static String calc(int N, int K, String S) {
        StringBuilder str;
        str = new StringBuilder();

        char[] charArray = S.toCharArray();
        for (int i = 0; i < N; i++) {
            char c = charArray[i];

            if (i + 1 == K) c = toLower(c);

            str.append(c);

        }
        return str.toString();
    }

