	static int bubbleSort(int count, ArrayList<Integer> array){
		boolean f = true;
		int r = 0;
		while(f){
			f = false;
			for(int j=array.size();j>0;j++){
				if(array.get(j) < array.get(j-1)){
					int temp = array.get(j);
					array.set(j, array.get(j-1));
					array.set(j-1, temp);
					f = true;
					r++;
				}
			}
		}
		return r;

	}

}

