	static int dp[] = new int[(int) 1e5 + 7]; 
	public static int fun(int ind) {
		if(ind == n-1) return 0; 

		else if(dp[ind] != -1) return dp[ind]; 

		else {
		         int max = (int) 1e5 + 7; 

		         for(int i = 1; i<=k; i++) {
