import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

public class Main {
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new
                    InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
    public static void main(String[] args) {
        FastReader fr = new FastReader();
        int x = fr.nextInt();
        int n = fr.nextInt();
        if(n==0){
            System.out.println(x);
        }
        else{
            Set<Integer> set = new HashSet<>();
            for (int i = 0; i < n; i++) {
                set.add(fr.nextInt());
            }
            if(!set.contains(x)){
                System.out.println(x);
            }
            else{
                int forward = x+1;
                while(set.contains(forward)){
                    forward++;
                }
                int backward = x-1;
                while(set.contains(backward)){
                    backward--;
                }
                int val1 = forward-x;
                int val2 = 0;
                if(backward<0){
                    val2+=(x);
                    val2+=(Math.abs(backward));
                }
                else{
                    val2=(x-backward);
                }
                if(val1<val2){
                    System.out.println(x+val1);
                }
                else{
                    System.out.println(x-val2);
                }
            }
        }
    }
}

import java.util.Scanner;

class Main {
	public static void main (String [] args) {
		Scanner scan = new Scanner (System.in);

		//プロセス数
		int n = scan.nextInt();
		String[] str = new String[n];
		int[] data = new int[n];

		//クオンタム
		int q = scan.nextInt();

		for (int i = 0; i < n; i++) {
			str[i] = scan.next();
			data[i] = scan.nextInt();
		}
		scan.close();

		Queue(str, data, q);
	}

	static void Queue (String[] str, int[] data, int q) {
		int count = 0;
		int quantum = 0;
		int head = 0;
		int top = data.length;

		while (true) {
			if ( data[head] != 0) {
				if ( data[head] < q) {
					quantum += 0;
					data[head] = 0;
					count++;
					System.out.println(str[head] + " " + quantum);
				} else {
					data[head] -= q;
					quantum += q;
				}
			}

			if (count == top) break;

			head++;
			if (head == top) head = 0;
		}
	}
}

