    int[] data = new int[1000];
    while(true){
      int sum = 0;
      double p = 0;
      double ave;
      int n = scanner.nextInt();
    for (int i = 0; i < n; i++){
      int a = scanner.nextInt();
      data[i] = a;
      sum += a;
    }
