    { 
        FastReader fr = new FastReader(); 

        int N = fr.nextInt();

        int[] h = new int[N];
        int[] dp = new int[N];

        Arrays.fill(dp, (int)2e9);
        dp[0] = 0;

        for(int i = 0; i < N; i++) {
