						x *= i;
					}
					minNum=true;
					a /= i;
				} else {
					i+=2;
				}
				if(a < i*i && !minNum) {
					break;
				}
			}

			if(!minNum) {
				x = a;
			}
			System.out.println(x + y - 2);

		}
	}

}

