			<= t[k]-t[k-1]) {
				if(Math.abs(x[k]-x[k-1]) + Math.abs(y[k]-y[k-1])
			- (t[k]-t[k-1]) % 2 == 0) {
					judge += 1;
				}else {
					judge += 0;
				}
			}else {
				judge += 0;
			}
		}

