        for(int i = 0; i < n + 1; ++i){
            a[i] = input.nextInt();
        }
        for(int i = 0; i < n; ++i){
            b[i] = input.nextInt();
        }
        long sum = 0;
        for(int i = 0; i < n; ++i){
            if(a[i] <= b[i]){
                sum += a[i];
                b[i] -= a[i];
            }
            else{
                sum += b[i];
                b[i] = 0;
            }
            if(a[i + 1] <= b[i]){
                sum += a[i + 1];
                b[i] -= a[i + 1];
            }
            else{
                sum += b[i];
                b[i] = 0;
            }
        }
        System.out.println(sum);
    }
}

