			while (first < 0 && quiz[i][1] > quiz[i][0] + tmp && quiz[i][0] + tmp < array.length && tmp < limit) {
				first = acBeginIndex.indexOf(quiz[i][0] + tmp++);
			}

			tmp = 0;

			int last = -1;

			while (last < 0 && quiz[i][0] < quiz[i][1] + tmp && quiz[i][1] + tmp >= 0 && tmp > limit * -1) {
