    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        int[] problem = new int[m];
        String[] answer = new String[m];
        for (int i = 0; i < m; i++) {
            problem[i] = sc.nextInt();
            answer[i] = sc.next();
        }

        int problemNumber = problem[0];
        int correct = 0;
        int wrong = 0;
        for (int i = 0; i < m; i++) {
