		String t = fs.next();
		int l = t.length();
		int min=l;
		int  step=0;
		for(int i=0;i<s.length();i++) // cabacc
		{                             // abc

			if(i+l>s.length())
			{
				break;
			}
			else
			{
				String sub = s.substring(i, i+l);
				for(int j=0;j<t.length();j++)
				{
					if(t.charAt(j)!=sub.charAt(j))
						step++;
				}
				if(step<=min)
					{
						min=step;
						step=0;
					}
			}
		}
		System.out.println(min);
	}


