		int ans = 0;
		int sub = 100;
		if(n==0) ans = x;
		else if(x<p[0]) ans=x;
		else if(x>p[n-1]) ans=x;
		else {
			if(x==p[0]) ans=x-1;
			else if(p[n-1]==x&&p[n-1]-p[n-2]<=1) ans=x+1;
			else {
				for(int i = 0; i < n-1; i++) {
					int left = p[i];
					int right = p[i+1];
						if(left>=x&&sub>left+1-x) {
							if(right-left>1) {
								ans=left+1;
								sub = ans-x;
							}

						}
						else if(left>=x&&sub<x-left+1) {
							break;
						}
						else if(right<=x&&sub>x-right-1) {
							if(right-left>1) {
								ans=right-1;
								sub = x-ans;
							}

						}
