		if(N%K==0){
			System.out.println(0);
		}
		else{
			if((N/2.0) >= N%K){
			N = N-(K*((N/K)+1))+N%K-1;
			System.out.println(N);
			if(N<=0){
				N=N*(-1);
			}
			}

			else{
			N = N-(K*(N/K))-N%K+1;

			if(N<=0){
				N=N*(-1);
			}
			System.out.println(N);
			}
		}
		}

		else{
			if(K>=N*2){
				System.out.println(N);
			}

