			//out.println((int) a[(-(mid))]);
			//out.println((int) a[(-(mid + 2))]);

			int c1 = Integer.MAX_VALUE;
			if (-(mid + 1) >= 0 && -(mid + 1) <= 100) {
				c1 = (int) a[(-(mid + 1))];
			}

			int c2 = Integer.MAX_VALUE;
			if (-(mid + 2) >= 0 && -(mid + 2) <= 100) {
				c2 = (int) a[(-(mid + 2))];
