		for(long i=L;i<R;i++){
			HashMap<Integer,Integer> tmp = new HashMap<>();
			for(long k=i+1;k<=R;k++){
				int x = (int)((i%2019)*(k%2019))%2019;
				ans = Math.min(ans, x);
