    private void run() {
        Scanner scanner = new Scanner(System.in);
        int N = scanner.nextInt();
        int[] h = new int[N];
        int[] dp = new int[N];
        for(int i = 0; i < N; i++) {
            h[i] = scanner.nextInt();
            dp[i] = Integer.MAX_VALUE;
        }

//        // もらうDP
//        dp[1] = Math.abs(h[0] - h[1]);
//        for(int i = 2; i < N; i++) {
