//        }
        // 配るDP
        dp[0] = 0;
        for(int i = 0; i < N-2; i++) {
            dp[i+1] = Math.min(Math.abs(h[i] - h[i+1]) + dp[i], dp[i+1]);
            dp[i+2] = Math.min(Math.abs(h[i] - h[i+2]) + dp[i], dp[i+2]);
        }
        dp[N-1] = Math.min(Math.abs(h[N-2] - h[N-1]) + dp[N-2], dp[N-1]);

