class AC {
	String s;
	AC(String s) {
		this.s = s;
	}
	int getAC() {
		boolean a = false;
		int ac = 0;
		for (int i = 0; i < s.length(); i++) {
			char ch = s.charAt(i);
			if (a) {
				if (ch == 'C') {
					ac++;
					a = false;
					continue;
				}
			}
			a = (ch == 'A') ? true : false;
		}
		return ac;
	}
}

