            long t=scan.nextLong();
            if(check(a,t)){
                ans++;
            }
        }
        System.out.println(ans);
    }
    private static boolean check(long[]a,long t){
        int l=0,r=a.length-1;
        while(l<r){
            int mid=(l+r)/2;
            if(a[mid]<t){
                l=mid+1;
            }
            else{
                r=mid;
            }
        }
        if(a[r]==t)return true;
        else return false;
    }
}

