		int list[] = new int[n];
		for(int i = 0; i < n; i++) {
			list[i] = scan.nextInt();
		}

		// Calculate the max profit.
		int max = list[1] - list[0];
		int key = list[0];
		for(int i = 0; i < n-1; i++) {
			for(int j = i+1; j < n; j++) {
				if(key < list[i]) break;
				if(max < list[j] - list[i]) {
					max = list[j] - list[i];
					key = list[i];
				}
			}
		}

		// Output the result.
		System.out.println(max);
	}
}

