				continue;
			}

			if(i > 0 && i < x) {
				ans = x - i;
			}
			else if(i > 0 && i > x) {
				ans = i - x;
			}
			else if(i == 0) {
				ans = x;
			}
			else if(i < 0) {
				ans = x + i;
				if(ans < 0) {
					ans = -1 * ans;
				}
			}

			if(ans < small) {
				small = ans;
				num = i;
			}


	}

