		printList(A,N);
		insertionSort(A,N);
	}

	static void insertionSort(ArrayList<Integer> A,int N){
		for(int i=1;i<N;i++){
			int v = A.get(i);
			int j=i-1;
			while(j>=0 && (v < A.get(j))){
				A.set(j+1,A.get(j));
				j--;
			}
			//this is the reason called a "InsertionSort"
			A.set(j+1, v);
			printList(A,N);
		}
	}
	static void printList(ArrayList<Integer> A,int N){
		StringBuilder builder = new StringBuilder();
		for(int i=0;i<N;i++){
			if(i>0){
				builder.append(" ");
			}
			builder.append(A.get(i));
		}
		System.out.println(builder);
	}
}

