class Main{
    static HashMap<Pair, Integer> colors;
    static ArrayList<Integer> edges[];
    public static void main(String[] args){
        FastScanner fsc=new FastScanner();
        int n=fsc.nextInt();
        edges=new ArrayList[n];
        for(int i=0;i<n;i++) edges[i]=new ArrayList<Integer>();
        Pair[] pairs=new Pair[n-1];
        int dim=0;
        for(int i=0;i<n-1;i++){
            int a=fsc.nextInt()-1, b=fsc.nextInt()-1;
            edges[a].add(b);
            edges[b].add(a);
            dim=Math.max(Math.max(dim, edges[a].size()), edges[b].size());
            pairs[i]=new Pair(a, b);
        }
        fsc.close();
        colors=new HashMap<>();
        coloring(0, -1, 0);
        System.out.println(dim);
        for(int i=0;i<n-1;i++) System.out.println(colors.get(pairs[i]));
    }
    static void coloring(int v, int parent, int color){
        int c=1;
        for(int u:edges[v]){
            Pair pair=new Pair(u, v);
            if(u!=parent){
                if(color==c) c++;
                colors.put(pair, c);
                coloring(u, v, c);
                c++;
            }
        }
    }
