        this.id2=id2;
    }
    @Override public boolean equals(Object o){
        if(! (o instanceof Pair)) return false;
        Pair p=(Pair) o;
        if((p.id1==id1 && p.id2==id2) || (p.id1==id2 && p.id2==id1)) return true;
        else return false;
