		}

		for (int i = 2; i <= n; i++) {
			if (dp[i] == Integer.MAX_VALUE) {
				dp[i] = 0;
			} else {
				dp[i] = dp[i - 1] % 1000000007 + dp[i - 2] % 1000000007;
			}
		}

		System.out.println(dp[n] % 1000000007);
	}
}

