class Solver {
    public void solve(long N) {
        long min = Long.MAX_VALUE;
        for (long i = 1; i * i <= N; i++) {
            if (N % i == 0) {
                min = Math.min(min, (i - 1) + (N / i - 1));
            }
        }
        System.out.println(min);
    }
}

