public class Main {
    public static void main(String[] args) {
        //コード
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.next());
        int d = Integer.parseInt(scanner.next());

        for(int i = 1; i < n; i++) {
            int bottom = i - d;
            int top = i + d;
            if(bottom == 1) {
                if(n % top == 0) {
                    System.out.println(n/top);
                    System.exit(0);
                } else {
                    System.out.println((n/top) + 1);
                    System.exit(0);
                }
            }
        }
        System.out.println(1);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        boolean[][] cards = new boolean[4][13];
        int n = scan.nextInt();

        if (n == 52) return;
        while (n != 0) {
            char image = scan.next().charAt(0);
            int num = scan.nextInt() - 1;

            switch (image) {
                case 'S':
                    cards[0][num] = true;
                    break;
                case 'H':
                    cards[1][num] = true;
                    break;
                case 'C':
                    cards[2][num] = true;
                    break;
                case 'D':
                    cards[3][num] = true;
                    break;
            }
            n--;
        }
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 13; j++) {
                if (cards[i][j] == false) {
                    switch (i) {
                        case 0:
                            System.out.println("S " + (j + 1));
                            break;
                        case 1:
                            System.out.println("H " + (j + 1));
                            break;
                        case 2:
                            System.out.println("C " + (j + 1));
                            break;
                        case 3:
                            System.out.println("D " + (j + 1));
                            break;
                    }
                }
            }
        }
    }

}

import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int cellNum = scanner.nextInt();
        int cells[] = new int[cellNum];
        boolean reslt = true;

        for (int i = 0; i < cellNum; i++) {
            cells[i] = scanner.nextInt();
        }

        int nextNum = 0;
        for (int i = cellNum; 0 < i; i--) {
            if (cellNum == i) {
                nextNum = cells[i - 1];
                continue;
            }
            int num = cells[i - 1];
            if (num - nextNum > 1) {
                reslt = false;
                break;
            } else if (num - nextNum == 1) {
                nextNum = num - 1;
            } else {
                nextNum = num;
            }
        }

        System.out.println(reslt? "Yes": "No");
    }
}

