	private static String rot(final int n, final String str) {
		String res = "";
		for (int i = 0; i < str.length(); i++) {
			char c = (char)((str.charAt(i) + n - 'A') % 26 + 'A');
			res = res + String.valueOf(c);
		}
		return res;
	}

