        }
        else {
            return upperBound(a, l,m,x);
        }
    }




    private static void mul(long A[][], long B[][]){
        int i,j,k,n=A.length;
        long C[][]=new long[n][n];
        for(i=0;i<n;i++){
            for(j=0;j<n;j++){
                for(k=0;k<n;k++){
                    C[i][j]=(C[i][j]+(A[i][k]*B[k][j])%mod)%mod;
                }
            }
        }
        for(i=0;i<n;i++) {
            for (j = 0; j < n; j++) {
                A[i][j]=C[i][j];
            }
        }
    }

    private static void power(long A[][], long base[][], long n) {
        if(n<2){
            return;
        }
        power(A, base, n/2);
        mul(A,A);
        if(n%2==1){
            mul(A, base);
        }
    }

