			}else {
				anagCount.put(sorted, 1);
			}
		}

		long ans = 0;
		for (int count : anagCount.values()) {
			ans += ((long)count)*(count-1)/2;
		}
		System.out.println(ans);
	}

	public static void main(String[] args) {
		new Main().solve();
	}
}

