            if(a[i] <= b[i]){
                ans += a[i];
                b[i] -= a[i];
                a[i] = 0;
                ans += Math.min(a[i+1], b[i]);
                a[i+1] = Math.max(0,a[i+1]-b[i]);
            }else{
                ans += b[i];
            }
        }
        System.out.println(ans);
    }
}

