		if (currentA > max) {
			return false;
		}

		aA[0] = currentA;
		for (int j = 0; j < bA.length; j++) {
			bA[j] = wk[0][j] - currentA;
		}
		for (int i = 0; i < aA.length; i++) {
			aA[i] = wk[i][0] - bA[0];
		}
		boolean isMatch = true;
		outside: for (int i = 0; i < bA.length; i++) {
			for (int j = 0; j < bA.length; j++) {
				isMatch = wk[i][j] == aA[i] + bA[j];
				if (!isMatch) {
					break outside;
				}
			}
		}
		return isMatch ? true : chkC(wk, max, currentA + 1, aA, bA);
	}

