    BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
    String[] strArray = new String[2];
    StringBuilder sb = new StringBuilder();
    String line;
    while (true) {
      line = br.readLine();
      strArray = line.split(" ");
      int h = Integer.parseInt(strArray[0]);
      int w = Integer.parseInt(strArray[1]);
      if(h == 0 && w == 0) {
        break;
      }
      for (int i = 0;i < h;i++) {
        if (i == 0 || i == (h - 1)) {
          for (int f = 0;f < w;f++) {
            sb.append("#");
          }
        }
        else {
          for (int f = 0;f < w;f++) {
            if (f == 0 || f == (w - 1)) {
              sb.append("#");
            }
            else {
              sb.append(".");
            }
          }
        }
        sb.append("\n");
      }
      sb.append("\n");
    }
    System.out.print(sb);
  }
}

