		//System.out.println("maxE"+(i+1)+":"+maxE[i]);
	}

		//判斷奇數偶數出現最多的數是否相同
		if(maxO[0]==maxE[0]) {
			if((n-maxO[1] + n - maxE[3])<(n-maxE[1] + n - maxO[3])) // 條件是這樣
				System.out.println(n-maxO[1]+n-maxE[3]);
