static void InsertionSort(int[] a){
getValue(a);
for(int i=1;i<a.length;i++){
int j=i-1;
int tmp=a[i];
while(j>=0&&a[j]>tmp){
a[j+1]=a[j];
a[j]=tmp;
j--;
}
getValue(a);
}
}

private static void getValue(int[] a){
