			int s = Integer.parseInt(tempS);
			int cnt = 0;
			// x y S-x-y
			for (int i = 0; i < s + 1; i++) {
				if (i > k) {
					continue;
				}
				for (int j = 0; j < s + 1; j++) {
					if (j > k) {
						continue;
					} else if (s - i - j > k) {
						continue;
					}

					if (i + j <= s) {
						//System.out.println(String.valueOf(i) + "," + String.valueOf(j) + "," + String.valueOf(s - i - j));
