            if(Check(scan.nextInt()))
            {
                Count++;
            }
        }

        System.out.println(Count);
    }

    public static boolean Check(int a)
    {
        if(a==2) return true;
        if(a%2!=0)
        {
            for(int i=3;i<Math.sqrt((double)a);i+=2)
            {
                if(a%i!=0) return false;
            }
            return true;
        }else{
            return false;
        }

    }
}

